-- Coupa -> canonical INVOICE_LINE (COUPA). Generated by tools/build_silver_sql.py.
SELECT 'COUPA' AS SOURCE_SLOT, 'Coupa' AS SOURCE_SYSTEM, SPLIT_PART(po.RAW:account.code::STRING, '-', 1) AS COMPANY_CODE, i.RAW:"invoice-number"::STRING AS INVOICE_ID,
  i.RAW:"order-header-num"::STRING AS PO_NUMBER, NULL::STRING AS PO_ITEM, i.RAW:supplier.id::STRING AS SUPPLIER_ID,
  i.RAW:"invoice-date"::DATE AS INVOICE_DATE, NULL::FLOAT AS INV_QTY, i.RAW:total::FLOAT AS INV_AMOUNT, i.RAW:currency.code::STRING AS CURRENCY
FROM {{ source('src_coupa', 'coupa_invoices') }} i LEFT JOIN {{ source('src_coupa', 'coupa_purchase_orders') }} po ON po.RAW:"po-number"::STRING = i.RAW:"order-header-num"::STRING
